# Query: get all vms where power_state is on
import sys
sys.path.insert(0, "/home/nutanix/cluster/bin")
import env
import gflags
gflags.FLAGS([])
from google.protobuf.text_format import Merge
from insights_interface.insights_interface_pb2 import GetEntitiesWithMetricsArg
from insights_interface.insights_interface import InsightsInterface, InsightsInterfaceError

insights_interface = InsightsInterface("127.0.0.1", "2027")
arg = GetEntitiesWithMetricsArg()
query = '''
query {
  entity_list { entity_type_name: "vm" }
  where_clause {
    comparison_expr {
      lhs { leaf { column: "power_state" } }
      operator: kEQ
      rhs { leaf { value { str_value: "on" } } }
    }
  }
  group_by {
    raw_columns { column: "vm_name" }
  }
  query_name: "auto_query"
}
'''
Merge(query, arg)
try:
    ret = insights_interface.GetEntitiesWithMetrics(arg)
    print(ret)
except InsightsInterfaceError as ex:
    print("Error Message: " + ex.message)
    print(ex.ret)
